function gcd(a,b){ a=Math.abs(a); b=Math.abs(b); while(b){ var t=b; b=a%b; a=t; } return a||1; }
function simplify(num,den){
  if(den===0) return {num:0,den:0,err:'div0'};
  if(den<0){ num=-num; den=-den; }
  var g=gcd(num,den); return {num:num/g, den:den/g};
}
function add(a,b,c,d){ return simplify(a*d+b*c, b*d); }
function sub(a,b,c,d){ return add(a,b,-c,d); }
function mul(a,b,c,d){ return simplify(a*c, b*d); }
function div(a,b,c,d){ return simplify(a*d, b*c); }
function toDecimal(num,den,dp){ if(!den) return null; var v=num/den; if(dp==null) return v; var f=Math.pow(10,dp); return Math.round(v*f)/f; }
function fracStr(f){ if(f.err) return "分母不能为 0"; return (f.num===0?"0":f.num+ (f.den===1?"":"/"+f.den)); }
function fromDecimal(dec, maxDen){
  maxDen=maxDen||100000;
  var negv=dec<0; dec=Math.abs(dec);
  var intp=Math.floor(dec), frac=dec-intp;
  if(frac===0) return simplify(intp,1);
  var loN=0,loD=1,hiN=1,hiD=1;
  while(true){
    var mN=loN+hiN, mD=loD+hiD;
    if(mD>maxDen) break;
    if(frac*mD > mN){ loN=mN; loD=mD; } else { hiN=mN; hiD=mD; }
    if(Math.abs(frac - mN/mD) < 1e-12) break;
  }
  var bestN,bestD,bestErr=Infinity;
  [[loN,loD],[hiN,hiD]].forEach(function(p){ var e=Math.abs(frac-p[0]/p[1]); if(e<bestErr){bestErr=e;bestN=p[0];bestD=p[1];} });
  var num=intp*bestD+bestN, den=bestD;
  if(negv){ num=-num; }
  return simplify(num,den);
}
function mixed(num,den){ var s=simplify(num,den); var w=Math.floor(Math.abs(s.num)/s.den); var r=Math.abs(s.num)%s.den; return {whole:w, num:r, den:s.den, neg:s.num<0}; }
var EXPORTS={ gcd:gcd, simplify:simplify, add:add, sub:sub, mul:mul, div:div, toDecimal:toDecimal, fracStr:fracStr, fromDecimal:fromDecimal, mixed:mixed };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.FractionForgePure = EXPORTS; }
